import json, pathlib, hashlib, sys
sys.stdout.reconfigure(encoding='utf-8')
W=pathlib.Path(__file__).parent
A=json.loads((W/'2026.10.13 Audit comercial comparativ R05 final.json').read_text(encoding='utf-8'))
AUD={r['id']:r for r in A['checklist']}
C={v:json.loads((W/f'2026.10.13 Werkvertrag {v} R05.json').read_text(encoding='utf-8')) for v in ['BERGER','PECH']}
COMP={v:{q['referinta']:q for g in A['mapare_inversa'] if g['prestator']==v for q in g['componente']} for v in C}
ROWS=[]
def add(i,tema,faza,cs,refs,continut,termen,evidenta,limite,pozitie=None,diferenta=None,tip='aliniat R05',de=None,prefs=None):
    br=refs.split(';') if refs else []
    pr=(prefs.split(';') if prefs else br)
    orig={v:[AUD[c][v.lower()] for c in cs.split(',')] for v in C}
    req={'continut_livrabil':continut,'termen_trigger':termen,'acceptare_evidenta':evidenta,'limite_excluderi':limite,'text_de':de or ''}
    ro={'id':i,'capitol_faza':faza,'criteriu':tema,'teme_60':cs.split(','),'cerinta_comuna':req,'tip_diferenta':tip,'diferenta_reala':diferenta or 'Cerința relevantă este aceeași în cele două texte R05; originea și repartizarea onorariului pot diferi.','pozitie_negociere':pozitie or 'Păstrăm această cerință comună pentru ambii; cerem răspuns explicit pe conținut și livrabil, fără reducere tacită de scop.'}
    for v,rr in [('BERGER',br),('PECH',pr)]:
        quotes=[{'referinta':r,'citat':COMP[v][r]['text_contract']} for r in rr if r in COMP[v]]
        ro[v.lower()]={'original':' '.join(dict.fromkeys(q['oferta'] for q in orig[v])),'r05_rezumat':continut if not diferenta else ('Vezi diferența concretă; cerința R05 este documentată în citatele de mai jos.'),'referinte_r05':quotes,'surse_original':[q['sursa'] for q in orig[v]],'referinte_selectate':rr}
    cer='Conținut: '+continut+' Termen: '+termen+' Evidență: '+evidenta+' Limite: '+limite
    ro['celule_publice']={'criteriu':i+' — '+tema,'cerinta_comuna':cer,'berger':ro['berger']['original']+' R05: '+('; '.join(br))+'.','pech':ro['pech']['original']+' R05: '+('; '.join(pr))+'.','diferenta_pozitie':ro['diferenta_reala']+' Poziția AG: '+ro['pozitie_negociere']}
    ROWS.append(ro)
def save(draft=True):
    obj={'data':'2026.10.13','titlu':'Cerințe comune pentru negocierea BERGER și PECH','versiune':'N01 — lucru' if draft else 'N01 — matrice completă','statut':'BAZĂ DE NEGOCIERE, NETRIMISĂ / NESEMNATĂ. R05 rămâne nemodificat. Noile cerințe comune sunt propuneri AG, nu acorduri primite.','principii':['Același pachet, livrabile, termene, acceptare și reguli pentru ambii, la valorile proprii: BERGER 45.000 EUR net și PECH 69.300 EUR net.','12 vizite fizice incluse, până la 6 opționale efective; 18 luni de la B0 real, distinct de T0 de proiectare. Tarifele suplimentare rămân BERGER n × 2.000/12 și PECH 450 EUR net/vizită.','Scopul suplimentar propus este o cerință de negociere legitimă. Diferențele reale de text se uniformizează explicit; valorile economice nu se egalizează.','Fără BauKG, fără management general REALiG. Asigurarea este verificare administrativă secundară, fără prag numeric AG nou sau multiplicare anuală.'],'matrice':ROWS,'surse':A['documente_verificate'],'limite':['Această matrice nu modifică și nu înlocuiește fișierele R05.','Nu este o acceptare a prestatorilor și nu este raport de comunicații noi EVA.','Citatele originale și R05 sunt păstrate distinct de cerința comună propusă.']}
    if not draft:
        obj.update(FINAL)
    name='2026.10.13 Cerinte comune negociere matrice lucru.json' if draft else '2026.10.13 Cerinte comune negociere matrice.json'
    (W/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(name,len(ROWS))

add('N001','Pachet comun integral','Pachet / obiect','C02,C09,C31,C38','§ 2(1);§ 11(1);Anexa 1, alineat 1','Proiectare structurală completă, planuri și liste, asistență, PI până la final, dosar ZT și BWB pentru întregul existent și intervențiile noi, în totalul propriu fiecăruia.','Proiectare de la T0; execuție 18 luni de la B0; închidere obișnuită aferentă inclusă.','Leistungsblatt comun, matrice de răspuns și livrabile nominalizate.','Execuția fizică, BauKG și managementul general REALiG sunt excluse.','Aceeași anexă de scop pentru ambii, cu confirmare/contrapropunere pe fiecare ID. Nicio reducere tacită pentru a conserva prețul.','Pachetul general R05 este comun. BERGER are PI separat 10.000 EUR; PECH îl extinde în Pos. 05, BWB în Pos. 06. Aceste alocări nu reduc rezultatul comun.','aliniat scop / valori distincte')
add('N002','Baze și versiuni confirmate','Înainte de T0','C22','§ 2(2);Anexa 2, alineat 1','Aceeași listă de autorizații, planuri, indici, arhitectură, predimensionare, investigații și date de la terți; se confirmă separat starea autorizată și starea curentă.','Listă confirmată înainte T0; primirea și lipsurile concrete în 3 zile lucrătoare.','Fișiere, indici, date, surse, recepție și responsabil pentru fiecare lipsă.','Primirea nu înseamnă validare tehnică; uploadul ulterior nu modifică tacit scopul.','Se anexează aceeași listă ambilor; referința PECH la LB se identifică exact, fără a presupune automat toate cerințele acceptate.')
add('N003','Identități și reprezentare','Administrativ înainte de semnare','C01','§ 1(1);§ 1(2);§ 1(3)','AG și AN sunt persoanele juridice indicate; semnatarul, datele de facturare și mandatele operaționale sunt nominalizate.','Înainte de semnare; mandatele înainte de comenzi suplimentare.','Firmenbuch/date actuale și tabel de persoane/împuterniciri.','Contactul tehnic nu primește implicit putere de schimbare a prețului sau de semnare.','Aceeași regulă de mandat pentru ambii. Datele efective diferite sunt anexă administrativă, nu diferență de scop.','BERGER FN/UID trebuie completate; PECH FN/UID sunt indicate și Ployer este contact. R05 aplică aceeași regulă de reprezentare.','date administrative distincte')
add('N004','Ordinea documentelor și acordul integral','Formarea acordului','C19,C58','§ 2(3);§ 2(4);§ 16(1);Anexa 5, alineat 1','Acordul nou și anexele comune guvernează; originalul rămâne nemodificat și complementar. Actul adițional ulterior prevalează numai în domeniul modificat.','La semnare bilaterală; orice modificare esențială ulterior.','Pachet complet semnat și anexe identificate.','AGB/ÖNORM contractuale numai prin acord expres; semnarea doar a ofertei vechi nu acceptă pachetul nou.')
add('N005','Verificarea conceptului și statică nouă','D1 / calcul','C03,C23','§ 3(1)','Verificarea predimensionării și conceptului fundației din 2022, datelor de zidărie și teren; statică de execuție nouă, proprie și semnată.','D1: T0 + 3 săptămâni; continuarea calculului pe D2–D5.','Baze, ipoteze verificate, calcul semnat și avertizări motivate.','Datele vechi utilizabile pot fi reutilizate; transmiterea lor fără verificare nu îndeplinește calculul.','Se confirmă același rezultat propriu și identificarea conceptului de bază; orice schimbare fundamentală reală ulterioară urmează procedura comună, nu supliment automat.','R05 are același scop. Original BERGER condiționează 13.000 EUR de lipsa schimbării relevante a conceptului; PECH 42.000 EUR trimite la LB.','aliniat R05 / baze economice originale diferite')
add('N006','Fundație, placă și lift','D2','C23','§ 3(2);Anexa 1, tabel 1, rând 5','Fundare/fundație și legătură nou-vechi, placă de 30 cm ca ipoteză verificabilă, groapă și puț de lift pe toate nivelurile, încărcările fabricantului și subzidiri cu secvență/armare.','D2: T0 + 6 săptămâni, înainte de lucrări, cu timp de control și corectare.','Calcul, planuri, liste, detalii, niveluri și sarcini integrate.','30 cm nu este grosime garantată înainte de dimensionare; hidroizolația este numai interfață structurală.','Același livrabil și termen propus ambilor; o corecție justificată a ipotezei se documentează, nu se certifică mecanic.')
add('N007','Existent, zidărie, planșee și goluri','D3','C05,C23','§ 3(2);Anexa 1, tabel 1, rând 4','Consolidarea Tram-/Dippelbaumdecken, planșeul compozit peste 3 OG din baza autorizată, pereți, stâlpișori, buiandrugi, goluri și schimbări; traseul sarcinilor, reazeme și legături nou-vechi.','D3: T0 + 8 săptămâni, înainte de intervenții.','Calcul și planuri pe fiecare element/gol, liste și succesiune sigură.','Lista efectivă de goluri se confirmă; vechiul [15] nu produce automat plafon ori supliment acceptat.','Aceeași listă de elemente/goluri și același conținut ambilor; PECH 6.000 EUR rămâne poziție economică, BERGER nu primește fictiv un preț separat.','Scopul R05 este comun; PECH are Pos. 02 separat, BERGER în calcul/planuri.','aliniat scop / alocare economică distinctă')
add('N008','Mansardă, lemn și oțel','D4','C23,C24','§ 3(3);Anexa 1, tabel 1, rând 3','Structura lemn/oțel a mansardei pe două niveluri, șarpantă, lucarne, atic, terase, diafragme, contravântuiri și traseul sarcinilor până la fundație.','D4: T0 + 10 săptămâni, înainte de comandă/fabricație.','Calcul, planuri de conducere/detaliu, clase, liste și forțe în îmbinări.','Fabricarea CNC/Abbund rămâne executantului; propriile detalii statice sunt AN.')
add('N009','Balcoane, scări, pereți de foc și coșuri','D5','C23','§ 3(3);§ 3(4);Anexa 1, tabel 1, rând 7','Balcoane de curte cu ancorare în existent, scări/podeste, pereți ai casei scării, ziduri de foc, interfețe cu vecinii și coșuri influențate de structură.','D5: T0 + 12 săptămâni, înainte de execuție.','Calcul, traseul sarcinilor și detalii de legătură/fixare.','Domeniul este influența structurală; nu management general al vecinilor sau concept general de incendiu.')
add('N010','Excavație, subzidiri și sprijiniri temporare','D2 / stări de execuție','C06','§ 3(4);Anexa 1, tabel 1, rând 6','Calcul și planuri pentru Verbau, subzidiri, sprijiniri, Pölzungen și stări temporare necesare: sarcini, geometrie, armare, succesiune, interfețe vecini și puncte de verificare.','D2 înainte de excavație; stările etapizate înainte de fiecare intervenție.','Planuri/calcul complet și haltepunkte documentate.','Nu BauKG, organizarea generală a șantierului sau amenajarea generală exterioară.','Se cere aceeași prestație ambilor în totalurile proprii; excluderea originală BERGER trebuie înlocuită expres în negociere.','R05 include la ambii. Original BERGER exclude calculul excavației, PECH îl prețuiește la 5.000 EUR.','aliniat R05 / extindere comercială distinctă')
add('N011','Rezistență, stabilitate, incendiu structural și seism','Toate D1–D5','C26','§ 3(5)','Verificări de rezistență, stabilitate și utilizare, dimensionarea necesară la foc a elementelor portante; verificarea reutilizării probelor seismice/existent și completarea necesară transformării.','Baze D1; calcule înainte de livrarea și execuția elementului.','Norme/versiuni, ipoteze, rezultate și limite în calcul.','Nu concept multidisciplinar general de incendiu sau audit seismic autonom fără legătură cu proiectul.')
add('N012','Cofraj, armare și planșee compozite','D2–D5 / planuri','C04,C24','§ 4(1);Anexa 1, tabel 1, rând 1','Geometrie, axe, cote, goluri, piese înglobate; beton/clase de expunere/acoperire; armare, ancorări, suprapuneri, rosturi, secvențe de betonare, liste și reacțiuni.','Cu livrabilul elementului, înainte de comandă/betonare.','Planuri coordonate, liste de armare și verificare plan–calcul.','Alocarea BERGER 20.000 EUR planuri versus PECH în Pos. 01 nu schimbă livrabilul comun.')
add('N013','Oțel, noduri, ancore și suduri','D2–D5 / detalii','C24','§ 4(2);Anexa 1, tabel 1, rând 2','Toate îmbinările relevante: profile/clase, plăci, șuruburi, dibluri, ancore, grosimi, suduri, distanțe, număr/aranjare, forțe și momente pe poziție, liste și protecții constructive.','Cu livrabilul elementului: D2 fundare/lift/sprijiniri, D3 existent/goluri, D4 mansardă, D5 balcoane/rest; înainte de comandă, fabricare și execuție.','Detalii dimensionate și forțe verificabile în calcul și planuri.','Nu se mută la executant dimensionarea necesară doar invocând planul de atelier.')
add('N014','Planuri de atelier, Abbund și planuri tardive de furnizori','Fabricație / interfețe','C25','§ 4(3);§ 7(2)','AN furnizează toate datele/detaliile statice proprii și verifică planurile fabricantului, prefabricatelor, ancorelor și diblurilor; verificarea ulterioară normală rămâne în pachet.','D5 include planurile primite la timp. Cele tardive: control obișnuit în 2 zile lucrătoare de la primire, complexitatea anunțată în aceeași perioadă cu termen concret; înainte de fabricare.','Raport/freigabe pe versiune; propriul set complet la D5 și registrul planurilor terțe.','Executantul creează planurile de fabricare/NC-CNC. Primirea tardivă singură nu justifică supliment sau mutarea nodurilor proprii după D5.','Aplicăm ambilor regula concretă D5 + verificări terțe ulterioare, ca propunere nouă comună.','R05 are aceeași repartizare proiectare/fabricare; nu exprimă complet regula comună de termen pentru planurile terțe ulterioare D5.','clarificare comună nouă')
add('N015','Cicluri de corecții și Planwechsel','Proiectare / schimbări','C27,C28','§ 4(4);§ 4(5)','Minimum 2 cicluri coerente pe plan și corectarea nelimitată a propriilor erori; un Planwechsel structural coordonat în conceptul convenit, cu calcule și anexe; Zuarbeit/abgleich la autorizare.','În calendarul comun înainte de execuție; deviația ce necesită autorizare se semnalează înainte de lucrări.','Versiuni, schimbări și răspunsuri documentate; dosar structural pentru planificatorul de autorizare.','O variantă fundamental nouă sau schimbare reală de concept urmează procedura de supliment; depunerea arhitecturală aparține Einreichplaner.')
