# Toate cele 401 componente sunt legate de criteriile de negociere; nu adăugăm rânduri mecanice publice.
def bind(v,ref,ids):
    q=COMP[v][ref]
    for i in ids:
        d=M[i][v.lower()]
        if ref not in d['referinte_selectate']:
            d['referinte_selectate'].append(ref)
            d['referinte_r05'].append({'referinta':ref,'citat':q['text_contract']})
for v in C:
    for ref in COMP[v]:
        if any(ref in r[v.lower()]['referinte_selectate'] for r in ROWS):continue
        ids=[]
        if ref.startswith('Anexa 2, tabel'):ids=['N002']
        elif ref=='Anexa 3, alineat 1':ids=['N049','N051']
        elif ref.startswith('Anexa 3, tabel 1, rând '):
            k=int(ref.rsplit(' ',1)[1]);ids={3:['N043'],4:['N051'],5:['N044'],11:['N018'],16:['N032']}[k]
        elif ref.startswith('Anexa 4, alineat '):
            k=int(ref.rsplit(' ',1)[1]);ids=({'BERGER':{5:['N034','N038'],7:['N037']},'PECH':{3:['N034','N038'],4:['N037']}}[v][k])
        elif ref.startswith('Anexa 4, tabel 2, rând '):
            k=int(ref.rsplit(' ',1)[1]);ids=['N069']
            if v=='PECH' and k==10:ids+=['N042']
            if v=='PECH' and k==15:ids+=['N026','N032','N061']
            if v=='BERGER' and k==7:ids+=['N026','N061']
            if (v=='PECH' and k==16)or(v=='BERGER' and k==8):ids+=['N062']
        elif ref.startswith('Anexa 4, tabel 3, rând '):
            k=int(ref.rsplit(' ',1)[1]);ids=['N063']if k==8 else (['N036']if k==6 else(['N061']if k==7 else['N069']))
        elif ref.startswith('Anexa 4, tabel 5')or(v=='PECH' and ref.startswith('Anexa 4, tabel 4')):ids=['N038']
        elif ref=='Anexa 6, alineat 1':ids=['N082','N083']
        elif ref=='Anexa 6, alineat 3':ids=['N084']
        elif ref.startswith('Anexa 6, tabel 1, rând '):
            k=int(ref.rsplit(' ',1)[1]);ids={1:['N003'],2:['N003'],9:['N075'],10:['N091']}[k]
        elif ref.startswith('Anexa 6, tabel 2, rând '):
            k=int(ref.rsplit(' ',1)[1]);ids={1:['N001'],2:['N020','N026'],3:['N050','N051'],4:['N064'],5:['N068','N074'],6:['N056','N058'],7:['N034','N038'],8:['N088']}[k]
        if not ids:raise ValueError('Componentă nemapată '+v+' '+ref)
        bind(v,ref,ids)

def refresh(r):
    r['cerinta_comuna'].pop('text_de',None)
    q=r['cerinta_comuna']
    r['celule_publice']['cerinta_comuna']='Conținut: '+q['continut_livrabil']+' Termen: '+q['termen_trigger']+' Evidență: '+q['acceptare_evidenta']+' Limite: '+q['limite_excluderi']
    for v in C:
        d=r[v.lower()]
        # Referințele integrale rămân în JSON; celula folosește secțiunile/anexele de reper.
        refs=list(dict.fromkeys(x.split(',')[0] if x.startswith('Anexa') else x for x in d['referinte_selectate']))
        r['celule_publice'][v.lower()]='Original: '+d['original']+' R05 actual: '+d['r05_rezumat']+' Reper: '+', '.join(refs)+'.'
    r['celule_publice']['diferenta_pozitie']=r['diferenta_reala']+' Poziția AG: '+r['pozitie_negociere']
for r in ROWS:refresh(r)
